mapper.select:
SELECT k.knowledge_id, k.problem, k.solution, k.source_type, k.source_id, k.status, k.create_time, k.update_time, (SELECT COUNT(*) FROM ai_question_log l WHERE l.matched_knowledge_id = k.knowledge_id) AS hit_count FROM ai_knowledge k
ORDER BY
k.update_time ${sortOrder}
hit_count ${sortOrder}
